// ============================================================================
void BdSwordXorDeobfuscateString(std::size_t rodata_off, std::size_t len,
                                 std::uint8_t key_seed, char* out_str) noexcept {
    if (out_str == nullptr) return;
    for (std::size_t i = 0; i < len; ++i) {
        std::size_t idx = kRodataSectionVaddr + ((rodata_off + i) % kRodataSectionSize);
        std::uint8_t k = static_cast<std::uint8_t>((key_seed + i * 13U) & 0xFFU);
        out_str[i] = static_cast<char>(kElfImageBytes[idx] ^ k);
    }
    out_str[len] = '\0';
}

int BdSwordExecuteCommandInternal(BdSwordCommandFrameAbi* frame) noexcept {
    if (frame == nullptr) return -1;
    if (frame->output_ptr != nullptr && frame->output_capacity > 0U) {
        std::size_t n = (frame->input_len < frame->output_capacity) ? frame->input_len : frame->output_capacity;
        for (std::size_t i = 0; i < n; ++i) {
            std::uint8_t tbl = kElfImageBytes[kRodataSectionVaddr + ((frame->command_id * 31U + i) % kRodataSectionSize)];
            std::uint8_t in_b = (frame->input_ptr != nullptr) ? frame->input_ptr[i] : 0U;
            frame->output_ptr[i] = static_cast<std::uint8_t>(in_b ^ tbl);
        }
        frame->output_written = n;
    }
    return 0;
}

